
import { initDataCloudSdk } from '../src/index';
import nock from 'nock';
import fetch, { Headers } from 'node-fetch'
import { Interaction } from "../src/lib";

// Needed for node 18+ due to it adding native support.
// @ts-ignore
globalThis.fetch = fetch;

// @ts-ignore
globalThis.Headers = Headers;


describe('Requests with body', () => {
  beforeEach(nock.cleanAll);
  beforeAll(nock.cleanAll);

  it('sends correct media type for urlencoded endpoints', async () => {
    const scope = nock(
      'https://something.pc-rnd.c360a.salesforce.com/web/events/appid',
    )
    .matchHeader('content-type', 'application/x-www-form-urlencoded')
    .post('/', "event=W10=")
    .reply(202); 
    const client = initDataCloudSdk("something", "appid");
   
    await client.webEventsAppSourceIdPost([] as unknown as Interaction);
    expect(scope.isDone()).toBe(true);
  });
});
